		var handle = default(HCorEnum);
		try
		{
			while (true)
			{
				var hr = instance.TryEnumUserStrings(ref handle, out var userString, 1, out var count);
				Marshal.ThrowExceptionForHR(hr);
				if (count == 0)
					yield break;
				if (count != 1)
					throw new InvalidOperationException("Native metadata enumerator returned an invalid item count.");
				yield return userString;
			}
		}
		finally
		{
			if (!handle.IsNull)
				instance.TryCloseEnum(handle);
		}
	}

