	private static string QueryGetUserString(IMetaDataImport instance, mdString userString)
	{
		var hr = instance.TryGetUserString(userString, null, 0, out var required);
		Marshal.ThrowExceptionForHR(hr);
		if (required == 0)
			return string.Empty;

		for (var attempt = 0; attempt < 3; attempt++)
		{
			var capacity = required;
			var buffer = new char[checked((int)capacity)];
			hr = instance.TryGetUserString(userString, buffer, capacity, out var actual);
			Marshal.ThrowExceptionForHR(hr);
			if (actual > capacity)
			{
				required = actual;
				continue;
			}

			return CreateString(buffer, actual, false);
		}

		throw new InvalidOperationException("Native buffer size did not stabilize.");
	}

	private static string CreateString(char[] buffer, uint count, bool trimTerminator)
	{
		var length = checked((int)count);
		if (trimTerminator && length > 0 && buffer[length - 1] == '\0')
			length--;
		return new string(buffer, 0, length);
	}
